88	public sealed class {{ .SystemClass }} : ISystemDefinition
89	{
90	    public string SystemName => "{{ .Name }}";
91	
92	    public void Define(SystemBuilder builder)
93	    {
94	{{- range .Components }}
95	        builder.{{ .Add }}("{{ .AppID }}")
96	{{- range .Calls }}
97	            {{ . }}
98	{{- end }};
99	{{- end }}
100	    }
101	}
102	`
