112		topicsFile           = template.Must(template.New("Topics.cs").Parse(topicsFileTmpl))
113		connectorsFile       = template.Must(template.New("Connectors.cs").Parse(connectorsFileTmpl))
114		connectorsFileLegacy = template.Must(template.New("Connectors.cs").Parse(connectorsFileLegacyTmpl))
115		developmentFile      = template.Must(template.New("Development.cs").Parse(developmentFileTmpl))
116		systemClassFile      = template.Must(template.New("SystemClass.cs").Parse(systemClassFileTmpl))
117	)
118	
119	// componentView is a Component with its builder call and chained wiring calls
120	// resolved for the system class template. Each call renders on its own line.
121	type componentView struct {
122		AppID string
123		Add   string   // AddExtractor | AddLoader
124		Calls []string // the chained calls in order, e.g. `.From(...)`, `.Publishes(...)`, `.WithSchedule(...)`
125	}
