142		if _, err := os.Stat(path); err != nil {
143			warnf("template rendered no %sDevelopment.cs placeholder — this release predates development definitions; generating connectors with local file transports (upgrade with --version <newer tag> for deployed transports and local service mocks)", m.ProjectName)
