150	// connector declarations. Like the system class it refuses to create the
151	// file — but here a missing placeholder means the template release predates
152	// connectors entirely, so the system is generated without From/To instead of
153	// failing: it reports false and the caller degrades the system class the
154	// same way. withDevelopment=false (a release with connectors but no
155	// development definitions) keeps the era's local file transports; otherwise
156	// connectors declare their deployed transport shape and the development
157	// definition owns the local resolution.
158	func writeConnectorsFile(dir string, m *Model, withDevelopment bool, warnf func(format string, args ...any)) (bool, error) {
159		path := filepath.Join(dir, "Connectors.cs")
160		if _, err := os.Stat(path); err != nil {
161			warnf("template rendered no Connectors.cs placeholder — this release predates connectors; generating the system without From/To (upgrade with --version <newer tag> to wire them)")
162			return false, nil
163		}
164		tmpl := connectorsFile
165		if !withDevelopment {
166			tmpl = connectorsFileLegacy
167		}
168		return true, renderTo(path, tmpl, m)
169	}
170	
171	// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
172	// system definition. It refuses to create the file: the rendered template
173	// must have left the placeholder, or its name derivation disagrees with
174	// this CLI and the write would add a second ISystemDefinition instead of
175	// replacing the placeholder. withConnectors=false (a template release that
176	// predates Connectors.cs) omits the From/To calls; withDevelopment=false
177	// (a release that predates development definitions, whose skeleton ships no
178	// Services.cs) omits the Uses calls.
179	func writeSystemClassFile(dir string, m *Model, withConnectors, withDevelopment bool) error {
180		path := filepath.Join(dir, m.SystemClass+".cs")
181		if _, err := os.Stat(path); err != nil {
182			return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
183		}
184	
185		views := make([]componentView, len(m.Components))
186		fieldByKey := map[TopicKey]string{}
187		for _, t := range m.Topics {
188			fieldByKey[t.TopicKey] = t.Field
189		}
190		connectorField := map[string]string{}
191		for _, c := range m.Connectors {
192			connectorField[c.Name] = c.Field
193		}
194		for i, c := range m.Components {
195			v := componentView{AppID: c.AppID}
196			topicField := fieldByKey[c.Topic]
197			field, hasConnector := connectorField[c.Connector]
198			hasConnector = hasConnector && withConnectors
199			if c.Kind == intropytemplate.BlockKindExtractor {
200				v.Add = "AddExtractor"
201				if hasConnector {
202					v.Calls = append(v.Calls, ".From(Connectors."+field+")")
203				}
204				v.Calls = append(v.Calls, ".Publishes(Topics."+topicField+")")
205				v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
206				// Gated on the same signal as From/To: a template release that
207				// predates Connectors.cs also pins an Intropy.Topology without
208				// WithSchedule, so the degraded shape must not call it.
209				if withConnectors {
210					v.Calls = append(v.Calls, `.WithSchedule("`+defaultExtractorSchedule+`")`)
211				}
212			} else {
213				v.Add = "AddLoader"
214				v.Calls = append(v.Calls, ".Subscribes(Topics."+topicField+")")
215				if hasConnector {
216					v.Calls = append(v.Calls, ".To(Connectors."+field+")")
217				}
218				v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
219			}
220			views[i] = v
221		}
222	
223		return renderTo(path, systemClassFile, struct {
224			Name        string
225			SystemClass string
226			Components  []componentView
227		}{m.Name, m.SystemClass, views})
228	}
229	
230	// usesCalls is the platform-service wiring every block gets: the framework's
231	// block builders require idempotency and business-incident routing, and the
232	// skeleton's Services.cs declares both refs. Gated on the development era —
233	// earlier skeletons ship no Services.cs and pin an Intropy.Topology without
234	// Uses.
235	func usesCalls(withDevelopment bool) []string {
236		if !withDevelopment {
237			return nil
238		}
239		return []string{".Uses(Services.Idempotency)", ".Uses(Services.BusinessIncidents)"}
240	}
241	
242	func renderTo(path string, tmpl *template.Template, data any) error {
243		var buf bytes.Buffer
244		if err := tmpl.Execute(&buf, data); err != nil {
245			return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
246		}
247		if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
248			return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
249		}
